// D-Soccer drone/controller firmware feed (public/firmware/dsoccer/index.json).
// The D-Soccer Flight configurator reads this list over the network and flashes the file it picks,
// after checking size and SHA-256 against these rows. Rows are generated by
// d_soccer_flight_tauri/tools/fw_publish.mjs; this test keeps the list and the files in step.
import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync, readdirSync } from 'node:fs';

const dir = new URL('../public/firmware/dsoccer/', import.meta.url);
const index = JSON.parse(readFileSync(new URL('index.json', dir), 'utf8'));
const DEVICE = { 0x10: 'drone', 0x20: 'controller' };

test('dsoccer firmware index: schema and one row per file', () => {
  assert.equal(index.schema, 'dsoccer-firmware/1');
  const files = readdirSync(dir).filter((f) => /\.(ax|br)$/.test(f)).sort();
  assert.deepEqual(index.firmware.map((f) => f.file).sort(), files);
});

test('dsoccer firmware index: size, sha256 and header match each file', () => {
  for (const f of index.firmware) {
    const b = readFileSync(new URL(f.file, dir));
    assert.equal(f.size, b.length, f.file);
    assert.equal(f.sha256, createHash('sha256').update(b).digest('hex'), f.file);
    const model = b.readUInt32LE(0), v = b.readUInt32LE(4);
    assert.equal(f.model, '0x' + model.toString(16).toUpperCase().padStart(8, '0'), f.file);
    assert.equal(f.device, DEVICE[(model >> 8) & 0xff], f.file);
    assert.equal(f.version, `${v >>> 24}.${(v >> 16) & 0xff}.${v & 0xffff}`, f.file);
    const pad = (n) => String(n).padStart(2, '0');
    assert.equal(f.date, `${b.readUInt16LE(12)}-${pad(b[14])}-${pad(b[15])}`, f.file);
  }
});

test('dsoccer firmware index: newest first per device', () => {
  for (const d of ['drone', 'controller']) {
    const dates = index.firmware.filter((f) => f.device === d).map((f) => f.date);
    assert.ok(dates.length > 0, d);
    assert.deepEqual(dates, [...dates].sort().reverse(), d);
  }
});
